 function apply(u){u={...u,equipment:{...u.equipment,armor:armorRecord(u.equipment?.armor,(u.id||u.characterId)+'-initial-armor')}};const out={...u},b=bonuses(u),intrinsic=u.baseAttributes&&u.potentials?G.attributesAt(u.baseAttributes,u.potentials,u.level):u.equipmentBase||Object.fromEntries(keys.map(k=>[k,Number(u[k])||1]));out.equipmentBase=copy(intrinsic);out.equipmentStatusBase=[...new Set([...(u.equipmentStatusBase||[]),...(u.statusImmunities||[]).filter(id=>!u.equipmentStatusGranted?.includes(id))])];out.equipmentStatusGranted=[...new Set([u.weapon,...Object.values(u.equipment||{})].flatMap(item=>item?.statusImmunities||[]))];out.statusImmunities=[...new Set([...out.equipmentStatusBase,...out.equipmentStatusGranted])];out.baseArmor=u.baseArmor??(Number(u.armor)||0);out.baseResistance=u.baseResistance??(Number(u.resistance)||0);for(const key of keys)out[key]=Math.max(1,intrinsic[key]+(b[key]||0));out.equipmentEffectBase={};for(const key of effectAttributes){const base=u.equipmentEffectBase?.[key]??(Number(u[key])||0);out.equipmentEffectBase[key]=base;out[key]=base+(b[key]||0);}out.armor=Math.max(0,out.baseArmor+(b.armor||0));out.resistance=Math.max(0,out.baseResistance+(b.resistance||0));if(out.weapon){out.weapon=weaponRecord(out.weapon,out.attack);out.attack=Number(out.weapon.power??out.weapon.attack??out.attack)||0;}out.baseMaxHealth=out.baseAttributes&&out.potentials?G.healthFromConstitution(out.constitution):(u.equipmentHealthBase??u.baseMaxHealth??u.maxSoldiers??G.healthFromConstitution(out.constitution));out.maxSoldiers=P.maxHealth(out);out.equipmentHealthBase=out.baseMaxHealth;delete out.weaponProficiencies;delete out.weaponExperience;return T.apply(out);}
