(function(root){
 'use strict';
 const node=typeof module!=='undefined'&&module.exports,H=node?require('./hero-quests.js'):root.HeroQuests,C=node?require('./recruitment-content.js'):root.RecruitmentContent,Cast=node?require('./chapter-cast.js'):root.ChapterCast,D=node?require('./world-data.js'):root.WorldData,N=node?require('./nearby-content.js'):root.NearbyContent;
 function actor(id,name,art,side='left'){const d=Cast.definitions[id];return C.actors[id]={id,name:name||d?.name||id,art:art||id,side};}
 function stage(place,objective,id,rows,choices,extra={}){const who=C.actors[id]||actor(id);return {place,objective,...extra,npc:{...who,observe:!!Cast.definitions[id]||root.CharacterGrowth.isGeneral({id}),turns:rows.map(([speaker,text])=>({speaker,text})),choices}};}
 const next=(label,next,extra={})=>({label,next,...extra}),fight=(label,battle,extra={})=>({label,battle,...extra});
 function finish(id,place,rows){const d=Cast.definitions[id];return stage(place||d.home,'与'+d.name+'商议去留',id,rows||[['npc','这里的事情总算安排好了。你们接下来准备去哪里？如果还需要人帮忙，我也想听听你们的打算。'],['hero','我们还会去各地走访，找愿意一起对付董卓的人。你要是暂时没有别的安排，可以先跟我们同行，路上也能互相照应。'],['npc','我愿意去。不过你们现在人手够了的话，我就先回去安排自己的事，往后再来找我也一样，不用急着今天就决定。']],[{label:'留下同行',recruit:true},{label:'先回'+D.placeMap[d.home].name,recruit:false}]);}
 function register(id,title,stages,battles={},extra={}){const d=Cast.definitions[id];const out=H.definitions[id]={id,name:d.name,title,country:d.country,place:stages[Object.keys(stages)[0]].place,type:d.type,home:d.home,category:'story',requiresChangshan:false,start:Object.keys(stages)[0],recommendedLevel:10,level:10,...extra,stages:{locked:{objective:''},...stages,complete:{objective:d.name+'已愿意相助'}},battles};
  for(const [phase,f]of Object.entries(battles)){if(!out.stages[phase])out.stages[phase]=out.stages[f.stage[0]];if(f.named)f.roster=()=>f.named.map((entry,i)=>{const [id,level=10,row]=Array.isArray(entry)?entry:[entry];return {...Cast.unit(id,level,{boss:true}),id:id+'-'+i,formationRow:row||'front'};});}
  if(!out.rumor&&!out.viaCourt)out.rumor=rumors[id]||('听说'+d.name+'最近在'+D.placeMap[out.place].name+'。你们想找他的话，可以先去那里问问，我也只是听过路的人说起，具体怎么样还得见了面才知道。');
  return out;
 }
 const rumors={diaochan:"天香阁的貂蝉姑娘正找人送信，听说几户织布的人家被抓了。她手上还留着交粮的凭据，想求个肯过问的人。",dongzhuo:"洛阳停兵了，城里开始开仓放人。董卓还在府中，听说正遣人核查那些被抓走的人家，不知这回是真是假。",xunyu:"长安的荀先生天天往书摊跑，找的都是战乱中散失的旧书。听说有辆书车没回来，连送书的伙计也没了音信。",jiaxu:"宛城让兵围了，郭汜张口便要粮。贾诩这几日都在府前看告示，你若入城，可去问问他。",zhangliao:"虎牢守将张辽，手下不敢扣车抢粮，过路人都念他的好。只是替董卓守关，他自己怕也有难处。",guanyu:"解良卖面的那家又让兵欺负了。幸亏有个长髯的拦着，好像叫关羽，正陪父母住在附近。",zhangfei:"下邳那个张飞，近来在城外喝得凶。人问他怎么不回去，他就瞪眼。良成那边的大娘见过，你问问她。",machao:"武威马将军又坐酒家了，一坐半日。旧宅叫人占了，听说家里还留着东西，他却总不肯回去。",huanggai:"武陵几个采药的入山未归，黄老将军正找带路人。你若有空入城，看看他身边还缺不缺帮手。",lvmeng:"吕蒙进山救人，自己也没回来。他娘等得饭都吃不下，黄将军正在打听，可别又出事。",luxun:"夷陵旧石阵里困着个年轻人，半日还在同一块石头旁打转。去看也记着带水，别再多困一个。",sunshangxiang:"孙家的姑娘这几日都在建业渡口，弓也背着。说是想去柴桑接人，家里偏不许她独行。",lvbu:"吕布府里的管事到处问赤兔马。将军不爱见说客，你若想拜访，不妨从这匹马问起。",huatuo:"宜城华先生正缺药，采药的人出去了迟迟不回。他愁的倒不是方子，怕山路上又有人出事。",menghuo:"建宁往南，孟获那座寨子近来不肯让外客进。要去先问寨老，别还没说话便叫人拿刀拦了。",zhangjiao:"巨鹿的井又见底了。乡亲等张先生来求雨，田里的苗可等不了，人都在晒场那边。",zhangbao:"营里张宝天天问广宗药车，伤者多，药眼看见底。他想出门也脱不开身，你回去便知。"};
 for(const d of Object.values(Cast.definitions))actor(d.id);
 actor('book-dealer','书贩','peddler');actor('village-aunt','大娘','neighbor-woman');actor('temple-keeper','守庙老人','villager');actor('stable-master','马场主人','laborer');actor('boatman','船夫','laborer');actor('camp-scout','斥候','imperial-soldier');actor('southern-elder','寨老','villager');actor('southern-woman','采药妇人','neighbor-woman');actor('palace-steward','府中管事','town-doctor');actor('river-guard','守军','imperial-soldier');actor('bandit-chief','盗匪头目','brigand');actor('medicine-apprentice','药童','villager');actor('tianxiang-keeper','天香阁管事','neighbor-woman');
 actor('herbalist','采药人','herbalist');actor('ganning','甘宁','ganning');
 const api={actor,stage,next,fight,finish,register,landmark:C.landmark};root.ChapterQuestKit=api;if(node)module.exports=api;
})(globalThis);


