 Object.assign(H.definitions.sunshangxiang.battles.spar,{solo:true,boss:true,scaleToHero:true,acceptDefeat:false,trainingWeapon:'练武短弓',trainingSkills:[{base:'sword-cut',name:'校场试射'}]});
